describe('Checkbox State Management', () => {
  beforeEach(() => {
    cy.visit('https://the-internet.herokuapp.com/checkboxes');
  });

  it('should toggle checkbox states and update form correctly', () => {
    // Verify initial state: first checkbox unchecked, second checked
    cy.get('[type="checkbox"]').eq(0).should('have.value', 'false');
    cy.get('[type="checkbox"]').eq(1).should('have.value', 'true');

    // Verify form displays initial state
    cy.get('[type="checkbox"]').eq(0).should('be.checked');
    cy.get('[type="checkbox"]').eq(1).should('be.checked');

    // Toggle first checkbox
    cy.get('[type="checkbox"]').eq(0).click();

    // Verify both checkboxes are now checked
    cy.get('[type="checkbox"]').eq(0).should('have.value', 'true');
    cy.get('[type="checkbox"]').eq(1).should('have.value', 'true');

    // Verify form reflects updated state
    cy.get('[type="checkbox"]').eq(0).should('be.checked');
    cy.get('[type="checkbox"]').eq(1).should('be.checked');

    // Toggle second checkbox
    cy.get('[type="checkbox"]').eq(1).click();

    // Verify only first checkbox remains checked
    cy.get('[type="checkbox"]').eq(0).should('have.value', 'true');
    cy.get('[type="checkbox"]').eq(1).should('not.have.value');

    // Verify form reflects final state
    cy.get('[type="checkbox"]').eq(0).should('be.checked');
    cy.get('[type="checkbox"]').eq(1).should('not.be.checked');
  });

  it('should handle edge case: unchecking all checkboxes', () => {
    // Verify initial state: first checkbox unchecked, second checked
    cy.get('[type="checkbox"]').eq(0).should('have.value', 'false');
    cy.get('[type="checkbox"]').eq(1).should('have.value', 'true');

    // Toggle first checkbox
    cy.get('[type="checkbox"]').eq(0).click();

    // Verify both checkboxes are now checked
    cy.get('[type="checkbox"]').eq(0).should('have.value', 'true');
    cy.get('[type="checkbox"]').eq(1).should('have.value', 'true');

    // Toggle second checkbox
    cy.get('[type="checkbox"]').eq(1).click();

    // Verify only first checkbox remains checked
    cy.get('[type="checkbox"]').eq(0).should('have.value', 'true');
    cy.get('[type="checkbox"]').eq(1).should('not.have.value');

    // Toggle first checkbox again
    cy.get('[type="checkbox"]').eq(0).click();

    // Verify both checkboxes are now unchecked
    cy.get('[type="checkbox"]').eq(0).should('have.value', 'false');
    cy.get('[type="checkbox"]').eq(1).should('have.value', 'false');

    // Verify form reflects all unchecked state
    cy.get('[type="checkbox"]').eq(0).should('not.be.checked');
    cy.get('[type="checkbox"]').eq(1).should('not.be.checked');
  });
});
